SOURCE = 'def _cold_start_droplet_number(qc, nc, inverse_density, aerosol_number, landmask):\n    from gpuwm.core.thompson_entry import MAKE_DROPLET_NUMBER_SOURCE, droplet_mean_diameter_m, make_droplet_number\n    alt = np.asarray(_host(inverse_density), dtype=np.float32)\n    temp_rho = (np.float32(1.0) / alt).astype(np.float32)\n    nwfa = np.broadcast_to(np.asarray(_host(aerosol_number), dtype=np.float32), qc.shape)\n    seed = (qc > np.float32(0.0)) & (nc <= np.float32(0.0))\n    surface_needed = seed & (nwfa * temp_rho <= np.float32(0.0))\n    if landmask is None:\n        if bool(surface_needed.any()):\n            raise ValueError(f"mp_physics=28 cold start: {int(np.count_nonzero(surface_needed))} cloudy cell(s) carry no aerosol, and real.exe\'s make_DropletNumber then sizes the droplets by land or water (XLAND), but this initialization was given no target LANDMASK; pass landmask=<static LANDMASK> to initialize_real")\n        xland = np.full(qc.shape[-2:], 1.0, dtype=np.float32)\n    else:\n        xland = np.where(np.asarray(_host(landmask), dtype=np.float64) >= 0.5, 1.0, 2.0).astype(np.float32)\n    xland3 = np.broadcast_to(xland, qc.shape)\n    seeded = np.array(nc, dtype=np.float32)\n    count = int(np.count_nonzero(seed))\n    receipt = {\'authority\': MAKE_DROPLET_NUMBER_SOURCE, \'rule\': \'qc > 0 and nc <= 0: nc = make_DropletNumber(qc*rho, nwfa*rho, xland) / rho, rho = 1/alt\', \'seeded_cells\': count}\n    if count:\n        rho_seed = temp_rho[seed]\n        rc = (qc[seed] * rho_seed).astype(np.float32)\n        per_volume = make_droplet_number(rc, (nwfa[seed] * rho_seed).astype(np.float32), xland3[seed])\n        seeded[seed] = (per_volume / rho_seed).astype(np.float32)\n        aerosol_cells = ~surface_needed[seed]\n        ocean_cells = surface_needed[seed] & (xland3[seed] > 1.5)\n        diameter = droplet_mean_diameter_m(rc, per_volume)\n        receipt.update({\'aerosol_branch_cells\': int(np.count_nonzero(aerosol_cells)), \'land_branch_cells\': int(np.count_nonzero(surface_needed[seed] & ~(xland3[seed] > 1.5))), \'water_branch_cells\': int(np.count_nonzero(ocean_cells)), \'number_per_cm3_min\': float(per_volume.min() * 1e-06), \'number_per_cm3_max\': float(per_volume.max() * 1e-06), \'mean_diameter_um_min\': float(diameter.min() * 1000000.0), \'mean_diameter_um_max\': float(diameter.max() * 1000000.0)})\n    return (seeded, seed, receipt)\n\ndef _cold_start_rain_ice_number(species, mass, number, inverse_density, temperature):\n    from gpuwm.core.thompson_entry import MAKE_RAIN_ICE_NUMBER_SOURCE, ice_mean_diameter_m, make_ice_number, make_rain_number, rain_median_volume_diameter_m\n    function, diameter_of, rule = {\'rain\': (make_rain_number, rain_median_volume_diameter_m, \'qr > 0 and nr <= 0: nr = make_RainNumber(qr*rho, T) / rho\'), \'ice\': (make_ice_number, ice_mean_diameter_m, \'qi > 0 and ni <= 0: ni = make_IceNumber(qi*rho, T) / rho\')}[species]\n    alt = np.asarray(_host(inverse_density), dtype=np.float32)\n    temp_rho = (np.float32(1.0) / alt).astype(np.float32)\n    seed = (mass > np.float32(0.0)) & (number <= np.float32(0.0))\n    seeded = np.array(number, dtype=np.float32)\n    count = int(np.count_nonzero(seed))\n    receipt = {\'authority\': MAKE_RAIN_ICE_NUMBER_SOURCE, \'rule\': rule, \'seeded_cells\': count}\n    if count:\n        if temperature is None:\n            raise ValueError(f"Thompson cold start: {count} cell(s) carry {species} mass and no number, and real.exe\'s make_{species.capitalize()}Number sizes them by temperature, but the closure was given none")\n        if callable(temperature):\n            temperature = temperature()\n        rho_seed = temp_rho[seed]\n        per_mass = (mass[seed] * rho_seed).astype(np.float32)\n        temp_seed = np.asarray(temperature, dtype=np.float32)[seed]\n        per_volume = function(per_mass, temp_seed)\n        seeded[seed] = (per_volume / rho_seed).astype(np.float32)\n        diameter = diameter_of(per_mass, per_volume)\n        receipt.update({\'number_per_m3_min\': float(per_volume.min()), \'number_per_m3_max\': float(per_volume.max()), \'diameter_um_min\': float(diameter.min() * 1000000.0), \'diameter_um_max\': float(diameter.max() * 1000000.0), \'diameter\': \'median volume diameter\' if species == \'rain\' else \'mean diameter 3/lambda\'})\n        if species == \'rain\':\n            receipt[\'supercooled_cells\'] = int(np.count_nonzero(temp_seed <= np.float32(271.15)))\n    return (seeded, seed, receipt)\n\ndef _thompson_cold_start_moment_closure(state, state_xp, cfg: RunConfig, inverse_density, *, aerosol_number=None, landmask=None, temperature=None) -> dict[str, object]:\n    from gpuwm.core.thompson_entry import R1, THOMPSON_ENTRY_AUTHORITY, THOMPSON_ENTRY_SOURCE, np_thompson_entry_numbers\n    alt = np.asarray(_host(inverse_density), dtype=np.float32)\n    with np.errstate(divide=\'ignore\', invalid=\'ignore\'):\n        density = 1.0 / np.asarray(alt, dtype=np.float64)\n    if not np.all(np.isfinite(density)):\n        raise ValueError(f"the initializer\'s inverse density is zero or not finite in {int(np.count_nonzero(~np.isfinite(density)))} cell(s), so the density Thompson\'s entry block works in cannot be formed there")\n    species: list[dict[str, object]] = []\n    written: list[str] = []\n    total = 0\n    seeds: dict[str, object] = {}\n    built_temperature: list[object] = []\n\n    def seed_temperature():\n        if not built_temperature:\n            built_temperature.append(temperature() if callable(temperature) else temperature)\n        return built_temperature[0]\n    from gpuwm.boundary_fields import COLD_START_SEEDED_NUMBERS\n    kinds = {\'qc\': \'cloud\', \'qr\': \'rain\', \'qi\': \'ice\'}\n    pairs = tuple(((kinds[mass], mass, number) for mass, number in COLD_START_SEEDED_NUMBERS[int(cfg.mp_physics)]))\n    for name, mass_field, number_field in pairs:\n        mass = _host_float32(getattr(state, mass_field))\n        number = _host_float32(getattr(state, number_field))\n        offenders = (mass > R1) & (number <= 0.0)\n        count = int(np.count_nonzero(offenders))\n        entry = {\'species\': name, \'mass_field\': mass_field, \'number_field\': number_field, \'offending_cells\': count, \'repaired_cells\': 0}\n        if name == \'cloud\':\n            seeded, seed_mask, seeds[name] = _cold_start_droplet_number(mass, number, inverse_density, 0.0 if aerosol_number is None else aerosol_number, landmask)\n        else:\n            seeded, seed_mask, seeds[name] = _cold_start_rain_ice_number(name, mass, number, inverse_density, None if temperature is None else seed_temperature)\n        if count or bool(seed_mask.any()):\n            closed = np_thompson_entry_numbers(name, mass, seeded, density)\n            fixed = np.array(seeded, dtype=np.float32)\n            fixed[offenders] = np.asarray(closed, dtype=np.float32)[offenders]\n            if not np.isfinite(fixed).all() or bool((fixed < 0.0).any()):\n                raise ValueError(f\'the cold-start moment closure produced a non-finite or negative {number_field}; the analyzed {mass_field} it was closed over is not a state the scheme can start from\')\n            getattr(state, number_field)[...] = state_xp.asarray(fixed, dtype=state_xp.float32)\n            entry[\'repaired_cells\'] = count\n            if count:\n                entry[\'repaired_number_min\'] = float(fixed[offenders].min())\n                entry[\'repaired_number_max\'] = float(fixed[offenders].max())\n            total += count\n            written.append(number_field)\n        species.append(entry)\n    return {\'schema\': COLD_START_MOMENT_CLOSURE_SCHEMA, \'droplet_number_seed\': seeds.get(\'cloud\'), \'rain_number_seed\': seeds[\'rain\'], \'ice_number_seed\': seeds[\'ice\'], \'repaired\': True, \'repaired_cells_total\': total, \'authority\': THOMPSON_ENTRY_AUTHORITY, \'mp_physics\': int(cfg.mp_physics), \'q_threshold_kg_kg\': float(R1), \'species\': species, \'note\': "cells with mass and a number at or below zero first take real.exe\'s make_DropletNumber, make_RainNumber and make_IceNumber (droplet_number_seed, rain_number_seed, ice_number_seed); cells with mass above the scheme\'s activity threshold and a number moment at or below zero were then written by the entry block; every other cell, an analysed number above zero included, keeps the value real.exe writes", \'written_state_fields\': written, \'density\': \'initializer moist specific volume, rho = 1/alt\', \'entry_block\': THOMPSON_ENTRY_SOURCE + \' through gpuwm.core.thompson_entry\', \'cells_without_mass\': \'exact FP32 zero, as real.exe writes them\'}\n\ndef build_hrrr_hydrometeor_vertical_disposition(source_fields: Mapping[str, object], source_level_order, source_pressure, surface_pressure, target_pressure, initialized_fields: Mapping[str, object], *, operator_replay) -> dict[str, object]:\n    if not source_fields or set(source_fields) != set(initialized_fields) or (not callable(operator_replay)):\n        raise ValueError(\'hydrometeor disposition source/state/replay inventory differs\')\n    order = np.ascontiguousarray(source_level_order, dtype=np.int32)\n    first_shape = tuple(next(iter(source_fields.values())).shape)\n    if len(first_shape) != 3 or order.shape != (first_shape[0],) or (not np.array_equal(np.sort(order), np.arange(first_shape[0]))) or any((tuple(value.shape) != first_shape for value in source_fields.values())):\n        raise ValueError(\'hydrometeor disposition source inventory is invalid\')\n    active = np.zeros(first_shape, dtype=np.bool_)\n    raw_positive = {}\n    for name in sorted(source_fields):\n        raw = _host_float32(source_fields[name])\n        if not np.isfinite(raw).all() or np.any(raw < 0.0):\n            raise ValueError(f\'hydrometeor disposition source {name} is invalid\')\n        raw_positive[name] = raw != 0.0\n        active |= _ordered_levels(raw, order) != 0.0\n    geometry = _hrrr_operator_geometry(source_pressure, surface_pressure, target_pressure, active)\n    if geometry[\'source_pressure\'].shape != first_shape:\n        raise ValueError(\'hydrometeor disposition pressure/source shapes differ\')\n    if np.any(~np.isin(geometry[\'operator_class\'], np.asarray([0, 1, 2, 3], dtype=np.uint8))):\n        raise AssertionError(\'WRF hydrometeor operator geometry is unclassified\')\n    production_support = np.zeros(first_shape, dtype=np.bool_)\n    level_replays = []\n    influencing_targets: dict[tuple[str, int, int], list[int]] = {}\n    level_input = np.zeros(first_shape, dtype=np.bool_)\n    for ordered_level in range(first_shape[0]):\n        level_input[ordered_level] = True\n        level_output = _host_float32(operator_replay(level_input))\n        level_input[ordered_level] = False\n        if level_output.shape != geometry[\'target_pressure\'].shape or not np.isfinite(level_output).all() or np.any(level_output < 0.0):\n            raise ValueError(f\'hydrometeor disposition source-level production replay failed at ordered level {ordered_level}\')\n        level_support = np.any(level_output != 0.0, axis=0)\n        production_support[ordered_level] = level_support\n        raw_level = int(order[ordered_level])\n        written = level_output.reshape(level_output.shape[0], -1)\n        for name, positive_mask in raw_positive.items():\n            for column in np.flatnonzero((positive_mask[raw_level] & level_support).ravel())[:_HRRR_DISPOSITION_EXAMPLE_LIMIT]:\n                influencing_targets[name, raw_level, int(column)] = [int(index) for index in np.flatnonzero(written[:, column] != 0.0)]\n        level_replays.append({\'ordered_source_level\': ordered_level, \'raw_source_level\': raw_level, \'supported_column_count\': int(np.count_nonzero(level_support)), \'support_mask_sha256\': _packed_mask_sha256(level_support), \'output\': array_correspondence_fingerprint(level_output)})\n        del level_output, level_support, written\n    del level_input, raw_positive\n    pressure_partition_receipt = _pressure_partition_crosscheck(geometry, active, production_support, order)\n    del active\n    raw_production_support = np.zeros_like(production_support)\n    raw_production_support[order] = production_support\n    packed_production_support = np.packbits(raw_production_support.ravel(), bitorder=\'little\')\n    production_support_receipt = {\'schema\': _HRRR_PRODUCTION_SUPPORT_SCHEMA, \'shape\': list(first_shape), \'encoding\': _HRRR_PRODUCTION_SUPPORT_ENCODING, \'mask_base64\': base64.b64encode(zlib.compress(packed_production_support.tobytes(), level=9)).decode(\'ascii\'), \'mask_sha256\': hashlib.sha256(packed_production_support.tobytes()).hexdigest(), \'support_count\': int(np.count_nonzero(raw_production_support)), \'level_replays\': level_replays}\n    del raw_production_support, packed_production_support\n    geometry_receipt = {\'source_pressure\': array_correspondence_fingerprint(geometry[\'source_pressure\']), \'surface_pressure\': array_correspondence_fingerprint(geometry[\'surface_pressure\']), \'target_pressure\': array_correspondence_fingerprint(geometry[\'target_pressure\']), \'source_level_order\': array_correspondence_fingerprint(order), \'source_level_order_values\': order.tolist(), \'production_target_support\': production_support_receipt, \'pressure_partition\': pressure_partition_receipt}\n    species_receipts = {}\n    for name in sorted(source_fields):\n        raw = _host_float32(source_fields[name])\n        ordered = _ordered_levels(raw, order)\n        positive = ordered != 0.0\n        labels = np.zeros(first_shape, dtype=np.uint8)\n        operator_class = geometry[\'operator_class\']\n        target_influencing = positive & production_support\n        unused = positive & ~production_support\n        excluded = unused & (operator_class >= 2)\n        labels[excluded] = operator_class[excluded]\n        labels[target_influencing] = _HRRR_DISPOSITION_CLASSES[\'TARGET_INFLUENCING\']\n        unsupported = unused & (operator_class <= 1)\n        labels[unsupported & (geometry[\'source_pressure\'] >= geometry[\'surface_pressure\'][None, :, :])] = _HRRR_DISPOSITION_CLASSES[\'WRF_BELOW_GROUND_OUTSIDE_TARGET_SUPPORT\']\n        labels[unsupported & (geometry[\'source_pressure\'] < np.min(geometry[\'target_pressure\'], axis=0)[None, :, :])] = _HRRR_DISPOSITION_CLASSES[\'WRF_ABOVE_TARGET_TOP_OUTSIDE_TARGET_SUPPORT\']\n        labels[unsupported & (labels == 0)] = _HRRR_DISPOSITION_CLASSES[\'WRF_NO_TARGET_STENCIL\']\n        if np.any(positive & (labels == 0)) or np.any(~positive & (labels != 0)):\n            raise AssertionError(f\'hydrometeor disposition partition failed for {name}\')\n        raw_labels = np.zeros_like(labels)\n        raw_labels[order] = labels\n        encoded = zlib.compress(raw_labels.tobytes(order=\'C\'), level=9)\n        counts = {}\n        mask_hashes = {}\n        examples = {}\n        for class_name, code in _HRRR_DISPOSITION_CLASSES.items():\n            class_mask = raw_labels == code\n            count = int(np.count_nonzero(class_mask))\n            counts[class_name] = count\n            mask_hashes[class_name] = _packed_mask_sha256(class_mask)\n            records = []\n            flat_indices = np.flatnonzero(class_mask.ravel())[:_HRRR_DISPOSITION_EXAMPLE_LIMIT]\n            for flat_index in flat_indices:\n                raw_level, y, x = np.unravel_index(int(flat_index), first_shape)\n                ordered_level = int(np.flatnonzero(order == raw_level)[0])\n                written_targets = []\n                if class_name == \'TARGET_INFLUENCING\':\n                    written_targets = influencing_targets[name, int(raw_level), int(y) * first_shape[2] + int(x)]\n                records.append(_hrrr_disposition_example(raw_field=raw, raw_labels=raw_labels, order=order, ordered_level=ordered_level, y=int(y), x=int(x), geometry=geometry, influencing_targets=written_targets))\n            examples[class_name] = {\'complete\': count <= _HRRR_DISPOSITION_EXAMPLE_LIMIT, \'total_count\': count, \'records\': records}\n        source_fingerprint = array_correspondence_fingerprint(raw)\n        live_fingerprint = array_correspondence_fingerprint(initialized_fields[name])\n        source_replay = _host_float32(operator_replay(labels != 0))\n        source_replay_fingerprint = array_correspondence_fingerprint(source_replay)\n        if list(source_replay.shape) != live_fingerprint[\'shape\'] or not np.isfinite(source_replay).all() or np.any(source_replay < 0.0):\n            raise ValueError(f\'hydrometeor disposition operator replay failed for {name}\')\n        del source_replay\n        influencing_replay = _host_float32(operator_replay(labels == _HRRR_DISPOSITION_CLASSES[\'TARGET_INFLUENCING\']))\n        if list(influencing_replay.shape) != live_fingerprint[\'shape\'] or not np.isfinite(influencing_replay).all() or np.any(influencing_replay < 0.0):\n            raise ValueError(f\'hydrometeor disposition operator replay failed for {name}\')\n        influencing_replay_fingerprint = array_correspondence_fingerprint(influencing_replay)\n        del influencing_replay\n        excluded_replay = _host_float32(operator_replay((labels != 0) & (labels != _HRRR_DISPOSITION_CLASSES[\'TARGET_INFLUENCING\'])))\n        if list(excluded_replay.shape) != live_fingerprint[\'shape\'] or not np.isfinite(excluded_replay).all() or np.any(excluded_replay < 0.0):\n            raise ValueError(f\'hydrometeor disposition operator replay failed for {name}\')\n        operator_replay_receipt = {\'schema\': \'gpuwm-wrf-q-binary-mask-production-replay-v1\', \'source_mask_sha256\': _packed_mask_sha256(raw != 0.0), \'target_influencing_mask_sha256\': _packed_mask_sha256(raw_labels == _HRRR_DISPOSITION_CLASSES[\'TARGET_INFLUENCING\']), \'excluded_mask_sha256\': _packed_mask_sha256((raw_labels != 0) & (raw_labels != _HRRR_DISPOSITION_CLASSES[\'TARGET_INFLUENCING\'])), \'source_output\': source_replay_fingerprint, \'target_influencing_output\': influencing_replay_fingerprint, \'excluded_output\': array_correspondence_fingerprint(excluded_replay), \'source_target_outputs_byte_equal\': source_replay_fingerprint == influencing_replay_fingerprint, \'excluded_output_all_exact_zero\': not bool(np.any(excluded_replay != 0.0))}\n        del excluded_replay\n        influencing_count = counts[\'TARGET_INFLUENCING\']\n        if influencing_count > 0 and int(live_fingerprint[\'nonzero_count\']) == 0:\n            raise ValueError(f\'WRF target-influencing analyzed hydrometeor source mass was lost for {name}\')\n        if influencing_count == 0 and int(live_fingerprint[\'nonzero_count\']) != 0:\n            raise ValueError(f\'WRF target-independent hydrometeor source produced unexpected initialized mass for {name}\')\n        species_receipts[name] = {\'shape\': list(first_shape), \'encoding\': _HRRR_DISPOSITION_ENCODING, \'labels_base64\': base64.b64encode(encoded).decode(\'ascii\'), \'labels_sha256\': hashlib.sha256(raw_labels.tobytes(order=\'C\')).hexdigest(), \'decoded_source_fingerprint_sha256\': _canonical_receipt_sha256(source_fingerprint), \'initialized_state_fingerprint_sha256\': _canonical_receipt_sha256(live_fingerprint), \'partition_complete\': True, \'source_nonzero_count\': int(source_fingerprint[\'nonzero_count\']), \'target_influencing_source_count\': influencing_count, \'wrf_excluded_source_count\': int(source_fingerprint[\'nonzero_count\']) - influencing_count, \'class_counts\': counts, \'class_mask_sha256\': mask_hashes, \'examples\': examples, \'operator_replay\': operator_replay_receipt}\n    receipt = {\'schema\': HRRR_HYDROMETEOR_VERTICAL_DISPOSITION_SCHEMA, \'operator\': dict(_HRRR_DISPOSITION_OPERATOR), \'geometry\': geometry_receipt, \'species\': species_receipts}\n    receipt[\'evidence_sha256\'] = _canonical_receipt_sha256(receipt)\n    return receipt'

